'use strict';
// Local interaction specimen only. No persistence, network, real identities or cloud writes.
const players=['我','小林','小周'];
const killCards=Array.from({length:15},(_,i)=>({n:i+1,owner:[1,4,7,11,15].includes(i+1)?0:[2,3,5,6,8].includes(i+1)?1:2,potted:i+1===4}));
const publicCards=Array.from({length:15},(_,i)=>({n:i+1,owner:i+1===6?0:i+1===9?1:null}));
const records={kill:[],score:[]};
let scored=false, toastTimer;
const query=new URLSearchParams(location.search).get('screen');
document.body.dataset.screen=['home','kill','score'].includes(query)?query:'home';
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2800);}
function go(page){document.body.dataset.screen=page;history.replaceState(null,'','?screen='+page);document.getElementById(page).scrollIntoView({behavior:'smooth',block:'start'});}
function cardMeta(n){const rank=n===1?'A':({11:'J',12:'Q',13:'K',14:'JOKER',15:'JOKER'}[n]||String(n));const suit=n>=14?'★':['♠','♥','♣','♦'][(n-1)%4];return{rank,suit,red:n===14||(n<14&&['♥','♦'].includes(suit))};}
function card(c,kind){const m=cardMeta(c.n);const mine=kind==='public'&&c.owner===0,other=kind==='public'&&c.owner===1;const classes=['playing-card',m.red?'red':'',c.potted?'potted':'',mine?'owner-me':'',other?'owner-lin':''].filter(Boolean).join(' ');const label=kind==='public'?`${c.n}号，${c.owner===null?'未分配，点击记给自己':'归'+players[c.owner]+'，点击修正'}`:`${c.n}号，${c.potted?'已进':'未进，点击标记已进'}`;return `<div class="card-wrap">${kind==='own'&&c.potted?`<button class="undo" data-undo="${c.n}" aria-label="撤销${c.n}号已进"><span>↶ 撤销</span></button>`:''}<button class="${classes}" data-${kind}="${c.n}" aria-label="${label}" ${kind==='public'?'aria-pressed="'+(c.owner!==null)+'"':''}><span class="rank ${c.n>=14?'joker-rank':''}">${m.rank}<small>${m.suit}</small></span><span class="number">${c.n}</span><span class="rank-bottom ${c.n>=14?'joker-rank':''}">${m.rank}<small>${m.suit}</small></span>${c.potted?'<span class="potted-label">已进</span>':''}${kind==='public'&&c.owner!==null?'<span class="owner-badge">'+players[c.owner]+'</span>':''}</button></div>`;}
function killCount(owner){return killCards.filter(c=>c.owner===owner&&!c.potted).length;}
function drawKill(){document.getElementById('kill-content').innerHTML=`<div class="opponents">${[1,2].map(i=>`<div class="opponent"><span class="avatar ${i===2?'blue':''}">${players[i].slice(-1)}</span><div>${players[i]}<small>剩<strong>${killCount(i)}</strong>颗</small></div></div>`).join('')}</div><h3 class="hand-title">我的牌 <small>剩 ${killCount(0)} 颗</small></h3><div class="hand">${killCards.filter(c=>c.owner===0).map(c=>card(c,'own')).join('')}<button class="add-card" data-action="transfer" aria-label="添加惩罚球"><b>＋</b><small>添加惩罚球</small></button></div><p class="helper">ⓘ　点击自己的牌，标记已进</p><div class="footer-action"><button class="primary" data-action="kill-result">记录本次结果</button></div>`;}
function scores(){return players.map((_,i)=>publicCards.filter(c=>c.owner===i).reduce((s,c)=>s+c.n,0));}
function drawScore(){const count=publicCards.filter(c=>c.owner!==null).length;const sums=scores();document.getElementById('score-content').innerHTML=`<p class="caption">当前进球分</p><div class="scores">${players.map((p,i)=>`<div class="score ${i===0?'mine':''}"><div class="who">${p}</div><strong>${sums[i]}</strong><small>分</small></div>`).join('')}</div><div class="progress-info"><span>已记录 ${count}/15 张</span><span>每人基准 40 分</span></div><div class="progress"><i style="width:${count/15*100}%"></i></div><div class="public-grid">${publicCards.map(c=>card(c,'public')).join('')}</div><p class="helper">ⓘ　点击未选牌，记给自己</p><button class="primary" data-action="score-save" ${count<15||scored?'disabled':''}>${scored?'本次结果已保存':'保存本次结果'}</button><p class="save-info">${scored?'已计入示例累计':count<15?'还有 '+(15-count)+' 张未记录':'完整输赢：'+sums.map((s,i)=>players[i]+' '+signed(s-40)).join(' / ')}</p>`;}
function signed(n){return(n>0?'+':'')+n;}
function sheet(page,title,body){const host=document.getElementById(page);host.querySelector('.overlay')?.remove();const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-top"><h3>${title}</h3><button class="close" aria-label="关闭">×</button></div>${body}</section>`;host.append(overlay);const prev=document.activeElement;const close=()=>{overlay.remove();if(prev?.isConnected)prev.focus();};overlay.querySelector('.close').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focus=[...overlay.querySelectorAll('button:not(:disabled),input,select')];const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});overlay.querySelector('button').focus();return overlay;}
function transfer(){let selected=null;const el=sheet('kill','选择转入的球',`<p>选择需要转入自己的号码。添加后恢复为未进；自己的牌不可重复添加。</p><div class="picker">${killCards.map(c=>`<button class="pick" data-pick="${c.n}" ${c.owner===0?'disabled':''}>${c.n}</button>`).join('')}</div><button class="primary confirm" disabled>确认添加</button><p>原持有人信息不在此展示；可见范围仍待业务确认。</p>`);el.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.pick);el.querySelectorAll('.pick').forEach(x=>x.classList.toggle('selected',x===b));el.querySelector('.confirm').disabled=false;});el.querySelector('.confirm').onclick=()=>{const c=killCards.find(x=>x.n===selected);if(!c||c.owner===0)return;c.owner=0;c.potted=false;el.remove();drawKill();toast(selected+'号已转入，剩余数量已更新');};}
function correct(n){if(scored){toast('已保存结果的更正权限尚待确定');return;}const c=publicCards.find(c=>c.n===n);const el=sheet('score',n+'号牌 · 当前归'+players[c.owner],`<p>示例最近修改人：${c.owner===1?'小林':'我'}。可退回公共区，或改给本场参与者。</p><label class="form-row">改归属<select id="new-owner">${players.map((p,i)=>`<option value="${i}" ${i===c.owner?'selected':''}>${p}</option>`).join('')}</select></label><button class="primary confirm">确认修改</button><button class="secondary return">退回公共区</button>`);el.querySelector('.confirm').onclick=()=>{c.owner=Number(el.querySelector('select').value);el.remove();drawScore();toast(n+'号归属已修改 · 修改人：我');};el.querySelector('.return').onclick=()=>{c.owner=null;el.remove();drawScore();toast(n+'号已退回 · 修改人：我');};}
function result(){const el=sheet('kill','记录本次结果',`<label class="form-row">赢家<select id="winner">${players.map((p,i)=>`<option value="${i}">${p}</option>`).join('')}</select></label><div id="remaining"></div><p id="preview"></p><button class="primary confirm">保存结果</button><p>当前剩余数作为预填值，请按线下结果核对。</p>`);let values=players.map((_,i)=>killCount(i));function calc(){const w=Number(el.querySelector('#winner').value);return players.map((_,i)=>i===w?values.reduce((s,n,j)=>s+(j===w?0:n),0):-values[i]);}function preview(){el.querySelector('#preview').textContent='本次结果：'+calc().map((n,i)=>players[i]+' '+signed(n)+'颗').join(' / ');}function rows(){const w=Number(el.querySelector('#winner').value);el.querySelector('#remaining').innerHTML=players.map((p,i)=>i===w?'':`<label class="form-row">${p}剩余颗数<input type="number" inputmode="numeric" min="0" step="1" value="${values[i]}" data-count="${i}"></label>`).join('');el.querySelectorAll('[data-count]').forEach(input=>input.oninput=()=>{values[Number(input.dataset.count)]=input.value===''?NaN:Number(input.value);const valid=values.every((v,i)=>i===w||(Number.isInteger(v)&&v>=0));el.querySelector('.confirm').disabled=!valid;if(valid)preview();else el.querySelector('#preview').textContent='请填写非负整数';});preview();}el.querySelector('#winner').onchange=rows;rows();el.querySelector('.confirm').onclick=()=>{records.kill.unshift({label:'杀球结果',scores:calc()});el.remove();toast('示例结果已保存，可在记录和累计查看');};}
function tab(page,which){document.querySelectorAll('#'+page+' [data-tab]').forEach(b=>{const active=b.dataset.tab===page+':'+which;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});if(which==='play'){page==='kill'?drawKill():drawScore();return;}const host=document.getElementById(page+'-content');const unit=page==='kill'?'颗':'分';if(which==='records')host.innerHTML=records[page].length?records[page].map(r=>`<div class="room-card"><h4>${r.label}</h4>${r.scores.map((s,i)=>`<div class="small-list"><span>${players[i]}</span><strong>${signed(s)}${unit}</strong></div>`).join('')}<p>本地示例 · 保存人：我</p></div>`).join(''):'<div class="placeholder">还没有保存记录<br>在记分页完成一次结果保存后查看</div>';else{const sums=players.map((_,i)=>records[page].reduce((s,r)=>s+r.scores[i],0));host.innerHTML='<h3>本房间 · '+(page==='kill'?'杀球':'打分')+'累计</h3>'+players.map((p,i)=>`<div class="room-card small-list"><span>${p}</span><strong>${signed(sums[i])}${unit}</strong></div>`).join('')+'<p class="muted">仅汇总本次打开页面后主动保存的示例结果</p>';}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.tab){tab(...b.dataset.tab.split(':'));return;}if(b.dataset.own){const c=killCards.find(c=>c.n===Number(b.dataset.own));if(c.potted)return;c.potted=true;drawKill();toast(c.n+'号已标记已进');return;}if(b.dataset.undo){const c=killCards.find(c=>c.n===Number(b.dataset.undo));if(!c.potted)return;c.potted=false;drawKill();toast(c.n+'号已恢复未进');return;}if(b.dataset.public){const c=publicCards.find(c=>c.n===Number(b.dataset.public));if(scored){toast('本次结果已保存，修改策略待确定');return;}if(c.owner===null){c.owner=0;drawScore();toast('已记 '+c.n+'分');}else correct(c.n);return;}const action=b.dataset.action;if(action==='transfer')transfer();else if(action==='kill-result')result();else if(action==='score-save'){if(scored||publicCards.some(c=>c.owner===null))return;scored=true;records.score.unshift({label:'打分完整结果',scores:scores().map(s=>s-40)});drawScore();toast('完整结果已保存');}else if(action==='join'){const el=sheet('home','房间码加入','<label class="form-row">房间码<input aria-label="房间码" maxlength="12" placeholder="输入房间码"></label><button class="primary confirm">查找示例房间</button><p>原型仅演示628391，不查询真实房间。</p>');el.querySelector('.confirm').onclick=()=>{if(el.querySelector('input').value.trim()!=='628391'){toast('示例房间码为628391');return;}el.remove();go('kill');};}else if(action==='create'){const el=sheet('home','创建房间 · 流程示例','<p>正式流程：创建房间 → 邀请好友 → 确认玩法与参与者。本设计稿可进入已有三人示例，未创建真实房间。</p><button class="primary confirm">进入杀球示例</button>');el.querySelector('.confirm').onclick=()=>{el.remove();go('kill');};}else if(action==='share')toast('开发时调用微信原生分享；本原型不发送消息');else if(action==='recent')toast('本设计稿展示2个最近房间示例');else if(action==='poker'||action==='nine')toast('本次交付只包含主页、杀球和打分设计');});
drawKill();drawScore();
